	bool ok;
	struct zcbor_string value;

	ok = zcbor_tstr_decode(ctxt->decoder, &value);
	if (!ok) {
		return MGMT_ERR_EINVAL;
	}

	ok = zcbor_tstr_encode(ctxt->encoder, &value);
	if (!ok) {
		return MGMT_ERR_ENOMEM;
	}

